-- ============================================================================
-- developer/config/player_settings.lua
-- ============================================================================
-- SINGLE SOURCE OF TRUTH for all player configuration.
-- Edit this commented baseline directly when needed. Project > Game Settings... Save publishes
-- creator_settings.lua overrides and preserves this file.
--
-- DO NOT edit mvtk/player/player.script - those are internal defaults only.
-- All gameplay tuning should happen here.
-- ============================================================================
-- Generated by Project > Game Settings...

return {
  -- SIZE
  -- The model's own files set its normal in-game size: 1.00 (100%) displays
  -- one image pixel as one world pixel. Player Size stretches the art for
  -- experiments; its unitless safe range is 1/7..8. After changing it, run
  -- "Prepare & Check" and Build to rebake sprite and collision resources.
  -- Pixel values below are world-size values at 1.00; the runtime multiplies
  -- body geometry and, when enabled below, movement by player_scale.
  player_scale = 1.00,
  -- Player/combat pixel-unit generation used for automatic override migration;
  -- unitless version, safe 1 or 2 (2 means the normal Player Size is 1.00).
  units_version = 2,
  -- When true (default), movement/kinematic pixel values (speeds, jump
  -- height, gravity, dash/glide/grapple values) also scale, preserving
  -- tile-relative game feel. When false, only body geometry scales.
  scale_movement = true,

  -- MOVEMENT
  walk_speed = 2100,
  run_speed = 3500,
  walk_speed_mode = "scaled",
  run_mode = "hold_button",
  run_threshold = 0.72,
  -- Dash uses the existing ground slide-to-run movement. Its ability unlock
  -- controls enabled at runtime; Slide must also be unlocked to start it.
  slide_to_run = {
    enabled = false,                 -- Starting unlock comes from ability_defaults.
    run_after_slide_when_held = true,-- Hold Slide through its finish to use run_speed.
    clear_run_on_release = true,     -- Releasing Slide returns to walking speed.
  },
  accel = 18,
  decel = 26,
  -- Horizontal recoil damping during hit-stun (per second). Lower values
  -- preserve more knockback; ordinary movement deceleration is independent.
  hurt_decel = 5,
  stop_epsilon = 5.25,
  -- Gameplay threshold for clearing the run gate near neutral. Controller
  -- hardware deadzone is configured once in game.project.
  walk_stop_deadzone = 0.20,
  air_accel_mult = 0.80,  -- Air control multiplier (1.0 = full control, 0.3 = floaty)

  -- WALK/RUN ANIMATION PACE (sprite and Spine)
  -- Playback follows horizontal movement relative to full walking speed.
  -- At walking speed the clip plays at 1x; running faster speeds up the legs.
  -- These settings affect animation only, never movement or camera speed.
  locomotion_animation = {
    enabled = true,        -- false restores each clip's authored playback speed.
    walk_multiplier = 0.8, -- Art tuning: raise if walking feet look too slow.
    run_multiplier = 5.0,  -- Lower if the run clip already has a faster stride.
    min_rate = 0.3,       -- Slowest playback while accelerating/decelerating.
    max_rate = 6.0,        -- Fastest playback, including movement speed boosts.
  },

  -- FOOTSTEP SOUND CADENCE
  -- Seconds between sound triggers at full  walk/run speed. Larger values
  -- mean slower footsteps. Slow analog walking spaces the sounds further
  -- apart; acceleration blends smoothly between walking and running cadence.
  -- This changes trigger timing, not the sound file's pitch or playback speed.
  footsteps = {
    enabled = true,        -- false silences movement-triggered footsteps.
    walk_interval = 0.24, -- Increase if walking still sounds too hurried.
    run_interval = 0.9,  -- Keeps the existing full-speed running cadence.
    min_speed_ratio = 0.02, -- Fraction of walk speed below which steps stop.
  },

  -- JUMPING
  gravity = -4200,
  jump_height = 448,
  extended_jump_height = 112,
  variable_jump_mode = "gravity_scale",
  jump_release_gravity_mult = 2.5,
  fall_gravity_mult = 1.5,  -- Extra gravity when falling for snappier descent
  jump_min_hold_time = 0.06,
  coyote_time = 0.12,
  jump_buffer = 0.12,
  air_jumps = 1,

  -- INPUT BUFFERING
  -- Stores button presses for this duration so they execute when available.
  -- Prevents missed inputs during cooldowns/animations (standard for action games).
  attack_buffer = 0.15,

  -- STATS
  max_health = 5,
  max_energy = 3,
  max_stamina = 100,

  -- COLLIDER
  collider_half_height = 59.9999575,
  collider_half_width = 46.45158,
  foot_floor_adjust = -15.48386,
  landing_snap_distance = 0,  -- Pixels above the floor where falling can auto-land. 0 disables the early ground snap.
  -- Ceiling collision tuning. head_margin is BASE px and scales with player_scale;
  -- collision_response.ceiling_response enables the terrain-contact safety net.
  head_margin = 27.096755,
  collision_response = {
    ceiling_response = true,
  },

  -- Spine bone names for the bundled BeardyBuck rig. Sprite mode ignores
  -- this block; customize the values when importing a different Spine rig.
  spine_physics = {
    bone_map = {
      body = "waist",
      foot_l = "foot_far",
      foot_r = "foot_near",
      head = "head",
    },
  },

  -- ABILITIES
  -- Ladder exit height above the player root, as a multiple of collider half
  -- height. Tune to the raised hands in your climb art; 2 matches this sprite.
  -- Scales with the collider automatically. Up exits onto support over the
  -- ladder; Left/Right pulls onto support beside it once the hands reach it.
  ladder_climb = {
    hand_height_ratio = 2,
    -- Minimum horizontal stick magnitude for ladder movement, facing and side
    -- exits. Filters sideways wobble that the engine's radial deadzone retains.
    side_input_threshold = 0.25,
    -- Horizontal input must be at least this multiple of vertical input before
    -- choosing a side. 1 accepts horizontal/diagonal intent; Up/Down stays centered.
    -- Lower this toward 0 to allow side exits while holding mostly Up.
    side_input_vertical_ratio = 1,
  },

  slide = {
    enabled = true,
    speed = 3850,
    duration = 0.35,
    -- Used only when abilities.lua has no slide_iframes ability; normally
    -- the Slide Invincibility unlock decides.
    iframes = false,
    lock_control = true,
  },

  air_dash = {
    enabled = true,
    speed = 3150,
    duration = 0.18,
    max_air_dashes = 1,
    -- Used only when abilities.lua has no air_dash_iframes ability; normally
    -- the Dash Invincibility unlock decides.
    iframes = false,
  },

  wall_climb = {
    enabled = false,
    speed = 1050,
    climb_speed = 1050,
    -- 0 = stay put on the wall. Set > 0 (px/s) for slow descent while clinging.
    stick_speed = 0,
    contact_grace = 0.12,
    -- Wall jump without wall climb (wall slide). Only used when the player has
    -- the wall_jump ability but not wall_climb.
    wall_jump = {
      -- Max fall speed (base px/s, scaled by player_scale) while holding toward a wall.
      slide_fall_speed = 350,
      -- Seconds after leaving the wall during which a wall jump still works.
      slide_coyote_time = 0.12,
    },
    ledge_climb = {
      enabled = true,
      climb_x = 56,
      climb_y = 112,
      up_threshold = 0.6,
      climb_time = 0.45,
      hang_enabled = true,
    },
  },

  -- Hold Interact at a contacted block to grab it. Disable this block to
  -- retain the original push-only behavior.
  block_grab = {
    enabled = true,
    pull_speed = 1225,
    release_grace = 0.15,
  },

  extended_jump = {
    enabled = false,
    hang_time = 0.15,
  },

  glide = {
    enabled = true,
    require_jump_held = true,
    gravity_mult = 0.22,
    max_fall_speed = 1575,
  },

  -- Ground Pound: in the air, hold Down and press Heavy Attack (or the
  -- GROUND_POUND binding) to slam straight down. The ability unlock decides
  -- enabled; base-scale pixel values scale when scale_movement is true.
  ground_pound = {
    enabled = false,               -- Runtime ability gate; unitless boolean, false or true.
    require_down_threshold = 0.6,  -- Stick-down magnitude that arms the slam; unitless, safe 0..1.
    slam_speed = 2450,             -- 2450 px/s downward at Player Size 1.00; safe 1..10000.
    impact_bounce = 595,           -- Base px/s upward pop on landing; safe 0..10000, 0 disables it.
    cooldown = 0.25,               -- Seconds after landing before another slam; safe 0..10.
    recovery = 0.10,               -- Seconds after landing with horizontal input ignored; safe 0..10.
  },

  grapple = {
    mode = "swing", -- "swing" moves like a pendulum; "pull" reels straight to the hook.
    -- False: hold Grapple to stay attached, then release the button to let go.
    -- True: keep swinging with the analog stick after releasing the button;
    -- press Grapple again or Jump to let go.
    stay_hooked = false,
    -- Share of velocity kept on a player let-go, before horizontal/up boosts.
    -- 0 drops, 1 keeps all momentum, 2 doubles it. Does not scale with player_scale.
    release_momentum_mult = 1.0,
    targets = "surfaces", -- Tagged rectangles, painted grapple layers and points; "ceilings" also catches terrain undersides.
    allow_walls = false, -- In "ceilings" mode, also allow untagged terrain wall faces.
    release_on_impact = true, -- End a swing on landing or a fast wall/ceiling impact.
    impact_release_speed = 262.5, -- Base pixels/second into a wall or ceiling needed to release.
    occlusion_tolerance_px = 14, -- Base-pixel slack for overlapping tags and rope obstructions.
    ground_clearance_px = 28, -- Base-pixel lift above the floor when attaching from the ground.
    launch_reel_speed = 2450, -- Base pixels/second used for the automatic ground-launch lift.
    swing_acceleration = 3500, -- Base pixels/second squared added by Left/Right pumping.
    swing_max_speed = 2100, -- Base pixels/second pumping limit; gravity may carry the swing faster.
    swing_speed_limit = 0, -- Base pixels/second safety limit; zero uses three times swing_max_speed.
    swing_drag = 0.12, -- Damping per second; lower values keep more pendulum energy. Does not scale.
    rope_length_px = 0, -- Base-pixel airborne rope length; zero keeps the distance when the hook catches.
    min_rope_length_px = 168, -- Base-pixel shortest rope, keeping space for the player's head.
    reel_enabled = false, -- Enable Up/Down reeling; otherwise the rope keeps its captured length after launch.
    reel_speed = 560, -- Base pixels/second shortened by Up or extended by Down when reeling is enabled.
    surface_clearance_px = 7, -- Base-pixel extra body clearance for pull arrival and minimum swing rope length.
    release_carry_time = 0.35, -- Seconds of reduced air braking after let-go, a lost anchor or room exit; zero disables.
    -- Gravity during airborne carry after let-go, a lost anchor or room exit.
    -- Lower is floatier; 1 uses base gravity. Fall/jump-release multipliers
    -- wait until carry ends; fast-fall still works. Impacts never float. Unscaled.
    release_gravity_mult = 0.6,
    -- Seconds to retry a fresh missed Grapple press while held; zero disables.
    -- Button up, attach or expiry clears it. Automatic releases never start
    -- retries. Seconds do not scale with player_scale.
    recast_window_s = 0.3,
    release_boost_px = 262.5, -- Base pixels/second added horizontally in the travel direction on let-go.
    release_up_boost_px = 0, -- Base pixels/second added upward on let-go; zero keeps the earned vertical speed.
    arrival_distance_px = 14, -- Base-pixel distance at which pull mode considers the anchor reached.
    -- Base-pixel reach; scales with player_scale when scale_movement is true.
    -- 1400 also reaches Lanternfall's high vaults when aiming diagonally upward.
    range_px = 1400,
    pull_speed = 3850, -- Base pixels/second toward the anchor when using pull mode.
  },
}
